abilities.compute:
(() => {
  const paths = new Set();
  const result = [];
  for (const record of $self.ability_records ?? []) {
    if (paths.has(record.document)) throw new Error("能力记录重复");
    paths.add(record.document);
    const definition = load(record.document);
    if (!definition || definition.kind === "index") throw new Error("无效的能力引用");
    if ([record.bonus, record.growth, record.override].some(value => value !== undefined && value < 0))
      throw new Error("能力调整不能为负数");
    if (definition.resource) throw new Error("此能力通过角色字段维护");
    const base = definition.attribute
      ? floor($self.stats[definition.attribute] / (definition.divisor ?? 1))
      : definition.base_value;
    const adjustment = (record.bonus ?? 0) + (record.growth ?? 0);
    if (adjustment || record.override !== undefined)
      result.push({ document: record.document, name: definition.name, base, value: record.override ?? base + adjustment });
  }
  return result;
})()
